import {WORLD_MONSTERS,ZONES} from './world-data.js?v=6.3.2';
import {MAP_BOSSES} from './map-bosses.js?v=6.3.2';
export const QUEST_REQUIREMENTS={junk:40,proof:5};
const bands=[[1,3],[4,6],[7,10],[11,16],[17,23],[33,47],[49,68],[74,100],[109,144],[158,203],[240,310],[335,430],[460,590],[630,800],[850,1080],[1120,1390],[1450,1780],[1850,2260],[2350,2840],[2950,3540]],parts=['霧晶殘屑','苔紋碎片','赤砂硬殼','霜骨結晶','星蝕粉晶','熾焰殘晶','潮汐遺珠','符紋零件','月影殘片','星宮碎核','浮空帆晶','精鍛齒核','以太稜晶','轟雷熔渣','天極星砂','星瀾潮晶','古誓木髓','永夜時沙','曜龍骨片','界源靈屑'];
export const JUNK_ITEMS=Object.fromEntries([...WORLD_MONSTERS,...Object.values(MAP_BOSSES)].map(m=>{const z=ZONES.findIndex(z=>z.id===m.map),zone=ZONES[z],t=(m.level-zone.min)/Math.max(1,zone.max-zone.min),cost=Math.round(bands[z][0]+t*(bands[z][1]-bands[z][0]));return ['junk_'+m.id,{name:m.name+'的'+parts[z],junk:true,cost:m.boss?cost*2:cost,map:m.map,monster:m.id,level:m.level}];}));
Object.assign(JUNK_ITEMS,{junk_fang:{name:'火狼幼獸的燼色絨毛',junk:true,cost:3,map:'petland',monster:'fang',level:1},junk_wisp:{name:'星光幼靈的微光粉塵',junk:true,cost:3,map:'petland',monster:'wisp',level:1},junk_shell:{name:'岩甲幼龜的幼岩甲片',junk:true,cost:4,map:'petland',monster:'shell',level:1},junk_sprout:{name:'生命芽靈的凝露嫩葉',junk:true,cost:3,map:'petland',monster:'sprout',level:1}});
export const PROOF_ITEMS=Object.fromEntries(ZONES.filter(z=>z.min>=51&&z.max<=99).map(z=>['proof_'+z.id,{name:({volcano:'燼火',abyss:'深淵',ruins:'古城',eclipse:'蝕月',celestial:'星宮'})[z.id]+'征途誓印',quest:true,cost:0,map:z.id}]));
export const BREAKTHROUGH_ITEM='proof_third_awakening';
PROOF_ITEMS[BREAKTHROUGH_ITEM]={name:'天極覺醒聖印',quest:true,thirdSeal:true,cost:0,description:'150級天極斷界龍5%掉落，集滿1枚於蒼穹樞城三轉；永不自動出售'};
export function questAcceptError(p,map){const z=ZONES.find(z=>z.id===map&&z.min>=51&&z.max<=99);if(p.location!=='town')return '請回村莊向征途引導官・艾琳接取';if(!z)return '此區域沒有征途任務';if(p.quests?.[map])return '已接取或完成此任務';if(p.level<z.min)return `需要Base ${z.min}級`;const prior=ZONES.filter(q=>q.min>=51&&q.min<z.min).find(q=>!p.quests?.[q.id]?.done);return prior?`請先完成${prior.name} Lv.${prior.min}–${prior.max}任務`:null;}
export function acceptZoneQuest(p,map,rng=Math.random){const error=questAcceptError(p,map);if(error)return {error};p.quests=p.quests||{};const monsters=WORLD_MONSTERS.filter(m=>m.map===map),m=monsters[Math.min(monsters.length-1,Math.floor(rng()*monsters.length))];return {quest:p.quests[map]={junk:'junk_'+m.id,proof:'proof_'+map,done:false}};}
export function turnInZoneQuest(p,map){const q=p.quests?.[map];if(p.location!=='town'||!q||q.done)return {error:'任務尚未接取、已完成或不在村莊'};const junk=p.bag.find(x=>x.id===q.junk),proof=p.bag.find(x=>x.id===q.proof);if((junk?.qty||0)<QUEST_REQUIREMENTS.junk||(proof?.qty||0)<QUEST_REQUIREMENTS.proof)return {error:`需要指定雜物${QUEST_REQUIREMENTS.junk}個與當區征途誓印${QUEST_REQUIREMENTS.proof}枚`};junk.qty-=QUEST_REQUIREMENTS.junk;proof.qty-=QUEST_REQUIREMENTS.proof;p.bag=p.bag.filter(x=>x.uid||x.qty>0);q.done=true;return {done:true};}
export function sellSelectedJunk(p,items){const selected=new Set(p.autoSellJunk||[]);let gold=0,count=0;for(const e of p.bag){if(e.uid||!selected.has(e.id)||!items[e.id]?.junk||items[e.id]?.dawnJunk)continue;const reserve=Object.values(p.quests||{}).some(q=>!q.done&&q.junk===e.id)?QUEST_REQUIREMENTS.junk:0,qty=Math.max(0,e.qty-reserve);if(!qty)continue;gold+=qty*items[e.id].cost;count+=qty;e.qty-=qty;}if(count){p.bag=p.bag.filter(e=>e.uid||e.qty>0);p.gold+=gold;}return {gold,count};}
